begin;
set local lock_timeout='5s';set local statement_timeout='30s';
-- Reuse the actual canonical uniqueness contract rather than add redundant locks.
-- The preceding migration remains immutable; no customer row or index is changed.
do $dependency$
begin
 if not exists(select 1 from pg_indexes where schemaname='djm_os' and indexname='organisations_tenant_club_name_unique' and indexdef=$index$CREATE UNIQUE INDEX organisations_tenant_club_name_unique ON djm_os.organisations USING btree (tenant_id, lower(btrim(name))) WHERE (organisation_type = 'club'::text)$index$) then raise exception 'Canonical club uniqueness prerequisite is required';end if;
end $dependency$;
do $patch$
declare spec jsonb; routine regprocedure;
begin
 for spec in select value from jsonb_array_elements($spec$[{"signature":"public.platform_server_agency_create_club_need(uuid,uuid,text,text,text,text,text,date)","hash":"5d8379b7f85c9e7d3771b144fa845447","definition":"CREATE OR REPLACE FUNCTION public.platform_server_agency_create_club_need(p_tenant_id uuid, p_actor_user_id uuid, p_club_name text, p_country text, p_position text, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_expires_on date DEFAULT NULL::date)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare org uuid;\nbegin\n perform private.platform_server_assert_agency_operator(p_tenant_id,p_actor_user_id);\n org:=private.platform_server_agency_ensure_club(p_tenant_id,p_club_name,p_country);\n return private.platform_create_club_need_for_record(p_tenant_id,p_actor_user_id,org,p_position,p_title,p_notes,p_expires_on);\nend;\n$function$\n"},{"signature":"private.platform_server_agency_ensure_club(uuid,text,text)","hash":"8189bd042c2aea911ae44ec0f443ccf6","definition":"CREATE OR REPLACE FUNCTION private.platform_server_agency_ensure_club(p_tenant_id uuid, p_name text, p_country text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_name text := nullif(btrim(coalesce(p_name, '')), '');\n  v_country text := nullif(btrim(coalesce(p_country, '')), '');\n  v_id uuid;\nbegin\n  if p_tenant_id is null or v_name is null or length(v_name) < 2 then\n    raise exception 'club_name_required';\n  end if;\n\n  if exists(select 1 from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is not null and lower(btrim(o.name))=lower(v_name)) and not exists(select 1 from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null and lower(btrim(o.name))=lower(v_name)) then raise exception 'This club is archived. Choose an active club record';end if;\n  select o.id\n  into v_id\n  from djm_os.organisations o\n  where o.tenant_id = p_tenant_id\n    and o.organisation_type = 'club'\n    and o.archived_at is null\n      and lower(btrim(o.name)) = lower(v_name)\n  order by o.created_at\n  limit 1;\n\n  if v_id is null then\n    begin\n      insert into djm_os.organisations (\n        tenant_id,\n        name,\n        organisation_type,\n        country,\n        canonical_key\n      )\n      values (\n        p_tenant_id,\n        v_name,\n        'club',\n        v_country,\n        null\n      )\n      returning id into v_id;\n    exception\n      when unique_violation then\n        select o.id\n        into v_id\n        from djm_os.organisations o\n        where o.tenant_id = p_tenant_id\n          and o.organisation_type = 'club'\n          and o.archived_at is null\n      and lower(btrim(o.name)) = lower(v_name)\n        order by o.created_at\n        limit 1;\n    end;\n  elsif v_country is not null then\n    update djm_os.organisations\n    set country = coalesce(country, v_country),\n        updated_at = now()\n    where id = v_id\n      and tenant_id = p_tenant_id;\n  end if;\n\n  if v_id is null then\n    raise exception 'club_create_failed';\n  end if;\n\n  return v_id;\nend;\n$function$\n"}]$spec$::jsonb) loop
  routine:=to_regprocedure(spec->>'signature');
  if not exists(select 1 from pg_proc where oid=routine and md5(prosrc)=spec->>'hash') then raise exception 'Unreviewed club identity writer %',spec->>'signature';end if;
  execute spec->>'definition';
 end loop;
end $patch$;
commit;
